      h: { ru: 'Функция с fill(255, 0, 0), wait(1), fill(0, 0, 0); затем on_button(1, имя) и forever().', kk: 'fill(255, 0, 0), wait(1), fill(0, 0, 0) бар функция; сосын on_button(1, аты) және forever().' },
