      judge: 'def check(log, spec):\n    t = after_event(log, "btn", 1)\n    if t is None: fail("судья нажал кнопку 1, но программа её не слушает: нужен on_button(1, функция) и forever()", "судья 1-түймені басты, бірақ бағдарлама оны тыңдамайды: on_button(1, функция) және forever() керек"); return\n    if find(log, lambda f: all_leds(f, "red"), 0) is not None and after_event(log, "btn", 1) > find(log, lambda f: all_leds(f, "red"), 0): fail("лента стала красной ещё до нажатия — эффект должен быть внутри функции кнопки", "лента басылмай тұрып қызыл болды — эффект түйме функциясының ішінде болуы керек"); return\n    t2 = held(log, lambda f: all_leds(f, "red"), 0.9, t)\n    if t2 is None: fail("после нажатия кнопки 1 лента должна гореть красным 1 секунду", "1-түймені басқаннан кейін лента 1 секунд қызыл жануы керек"); return\n    if find(log, off_all, t2 + 0.9) is None: fail("потом лента должна погаснуть", "сосын лента сөнуі керек")',
