      h: { ru: 'Список пауз [0.3, 0.26, 0.22, 0.18, 0.14, 0.1] и цикл for p in pauzy: fill маджентой, wait(p), fill зелёным, wait(p).', kk: 'Кідірістер тізімі [0.3, 0.26, 0.22, 0.18, 0.14, 0.1] және for p in pauzy циклі: маджентамен fill, wait(p), жасылмен fill, wait(p).' },
      a: 'def fill(r, g, b):\n    for i in range(9):\n        strip(i, r, g, b)\n    show()\n\nfor p in [0.3, 0.26, 0.22, 0.18, 0.14, 0.1]:\n    fill(255, 0, 255)\n    wait(p)\n    fill(0, 255, 0)\n    wait(p)\nfill(0, 0, 0)',
      judge: 'def check(log, spec):\n    fr = frames(log)\n    mags = [i for i, (t, f) in enumerate(fr) if all_leds(f, "magenta")]\n    if len(mags) < 6: fail("нужно 6 периодов (маджента 6 раз), а вижу %d" % len(mags), "6 период керек (маджента 6 рет), ал көргенім %d" % len(mags)); return\n    durs = [fr[i + 1][0] - fr[i][0] for i in mags if i + 1 < len(fr)]\n    if durs[0] < 0.25: fail("первая фаза должна быть долгой — 0.3 секунды", "бірінші фаза ұзақ болуы керек — 0.3 секунд"); return\n    if durs[-1] > 0.13: fail("последняя фаза должна быть короткой — 0.1 секунды", "соңғы фаза қысқа болуы керек — 0.1 секунд"); return\n    for a, b in zip(durs, durs[1:]):\n        if b > a + 0.01: fail("паузы должны только уменьшаться", "кідірістер тек кемуі керек"); return',
