    { ru: 'Две ловушки на одной кнопке: второй on_button(1, …) заменит первый.', kk: 'Бір түймеде екі қақпан: екінші on_button(1, …) біріншісін ауыстырады.' },
    { ru: 'Забыл global hits — счётчик всегда 1.', kk: 'global hits ұмытылды — санауыш әрқашан 1.' }
